-- Create "notifications" table
CREATE TABLE "notifications" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "alert_type" character varying NOT NULL, "event" jsonb NOT NULL, "attempts" bigint NOT NULL DEFAULT 0, "next_attempt_at" timestamptz NOT NULL, "last_error" character varying NOT NULL DEFAULT '', "created_at" timestamptz NOT NULL, "endpoint_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "notifications_endpoints_notifications" FOREIGN KEY ("endpoint_id") REFERENCES "endpoints" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "notification_endpoint_id_alert_type_id" to table: "notifications"
CREATE INDEX "notification_endpoint_id_alert_type_id" ON "notifications" ("endpoint_id", "alert_type", "id");
